#!/usr/bin/env python3
"""Build final specimen collateral from the approved identity; print exports use one page box."""
import hashlib
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parent.parent
SITE=ROOT/'site'
VERSION=hashlib.sha256((SITE/'assets/theme.js').read_bytes()).hexdigest()[:12]
LOGO='<span class="brand-logo" data-logo-slot aria-hidden="true"></span>'
EXAMPLE='Example only — fictitious document; not valid for payment or signature.'
FOOT='<footer class="docfoot"><b>99 Invest Ltd · ninetynine.eu · contact@ninetynine.eu</b><span>Registered address, registration number and VAT: [UNVERIFIED — confirm before publication]</span><small>'+EXAMPLE+'</small></footer>'
def header(label):return '<div class="dochead">'+LOGO+'<span class="meta">'+label+'</span></div>'
def table(head, rows):return '<table><thead><tr>'+''.join('<th>'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table>'
docs=[]
docs.append(('business-card','Business card','85 × 55 mm', '<div class="card-front">'+LOGO+'<div><h2>Paul Gauci</h2><p>Director · example contact</p></div><div><a href="mailto:paul@ninetynine.eu">paul@ninetynine.eu</a><br><a href="https://ninetynine.eu">ninetynine.eu</a></div><small>Software · Hosting · Continual improvement</small></div>'))
docs.append(('email-signature','Email signature','Offline reference', '<div class="signature">'+LOGO+'<h2>Paul Gauci</h2><p>Director · 99 Invest Ltd</p><a href="mailto:paul@ninetynine.eu">paul@ninetynine.eu</a><br><a href="https://ninetynine.eu">ninetynine.eu</a><p class="muted">One to ninety-nine. We start at one.</p><small>Example signature. Legal details pending confirmation.</small></div>'))
docs.append(('letterhead','Letterhead','A4',header('Correspondence · example')+'<div class="body"><p class="meta">02 November 2026 · Ref NN-L-0142</p><p>Ms Elena Vella<br>Operations Director<br>Northwind Trading Ltd · fictional client</p><h1>Quoting and order intake</h1><p>Dear Elena,</p><p>Thank you for showing us how your team prepares customer quotations. We propose starting with the steps that require repeated copying between spreadsheets, emails and your accounts system.</p><p>Our first stage will document the current process, the information people need and what a useful improvement would look like. We will agree the scope, assumptions and definition of done before preparing a written proposal.</p><p>If the proposal is accepted, we can design and build the software, help your team adopt it and agree the hosting, maintenance and enhancement arrangements needed after launch.</p><p>We will review the quoting workflow with your operations team first. Order intake and reporting can then be considered as separately agreed next steps.</p><p>Kind regards,</p><p><strong>Paul Gauci</strong><br>99 Invest Ltd · example signatory</p></div>'+FOOT))
docs.append(('proposal','Proposal','A4',header('Proposal · fictional example')+'<div class="body"><p class="meta">Northwind Trading Ltd · NN-P-0142 · 02 November 2026</p><h1>Less copying.<br>More time for customers.</h1><p>A proposed quoting workspace connecting customer records, product information and approvals, with clear ownership from scoping to ongoing improvement.</p>'+table(['Stage','Proposed scope','Review'],[['01 · Discovery','Process workshop, requirements and definition of done','Before build'],['02 · Software development','Quote preparation, approvals and accounts connection','At agreed milestones'],['03 · Hosting','Deployment, monitoring and backup arrangements','As contracted'],['04 · Maintenance','Defect handling, updates and agreed support','Regular review'],['05 · Enhancement','Reporting, automation and new features','Separately scoped']])+'<h2>Assumptions</h2><ul><li>Read-only accounts-system access is available.</li><li>Named operations staff can review prototypes.</li><li>Customer records can be exported in an agreed format.</li></ul><h2>Commercial arrangements</h2><p>Investment, delivery dates, acceptance criteria and service levels are agreed in a written proposal. No public prices or guaranteed savings are implied.</p></div>'+FOOT))
docs.append(('quote','Quote','A4',header('Quotation · fictional example')+'<div class="body"><p class="meta">NN-Q-0142 · prepared 02 November 2026</p><h1>Quoting workspace</h1><p><strong>Prepared for:</strong> Northwind Trading Ltd (fictional client)<br><strong>Review by:</strong> 30 November 2026 (illustrative)</p>'+table(['Work package','Deliverable','Commercial basis'],[['Scoping','Workshop and agreed scope','Private proposal'],['Software development','Quote preparation and approvals','Private proposal'],['Hosting and operation','Agreed environment and monitoring','Private proposal'],['Ongoing support','Maintenance and enhancement plan','Private proposal']])+'<h2>Not an offer for acceptance</h2><p>This document illustrates layout only. The actual scope, exclusions, delivery dates, prices, VAT treatment and payment terms must be agreed in a separately issued quotation.</p><p>VAT number/status: [UNVERIFIED — confirm before publication]</p><div class="note">No amounts are published in this specimen. Request a scoped proposal at contact@ninetynine.eu.</div></div>'+FOOT))
docs.append(('invoice','Invoice','A4',header('Invoice specimen · not payable')+'<div class="body"><p class="meta">NN-INV-0207 · 02 November 2026</p><h1>Invoice specimen</h1><p><strong>From:</strong> 99 Invest Ltd<br><strong>Bill to:</strong> Northwind Trading Ltd (fictional client)<br><strong>Period:</strong> October 2026 (illustrative)</p>'+table(['Description','Basis','Amount'],[['Software maintenance','Agreed scope','Not issued'],['Hosting and monitoring','Agreed service','Not issued'],['Enhancement work','Approved change request','Not issued']])+'<div class="totals"><p>Subtotal <strong>Not issued</strong></p><p>VAT treatment <strong>Unverified</strong></p><p>Balance due <strong>Not payable</strong></p></div><h2>Payment instructions</h2><p>None. This fictional specimen is not a tax invoice, demand for payment or proof of an agreement. No bank account details are included.</p><p>Registered address, registration number and VAT number/status require confirmation before any real invoice is issued.</p></div>'+FOOT))
css='''*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--paper);font:16px/1.6 var(--font-body)}a{color:inherit}header.page,main,.pagefoot{max-width:1200px;margin:auto;padding:40px 24px}header.page h1{font-size:clamp(2rem,4vw,3.4rem);line-height:1.05;margin:12px 0}header.page p{color:var(--sand);max-width:65ch}.eyebrow,.meta{font-family:var(--font-mono);font-size:.72rem;letter-spacing:.1em;text-transform:uppercase}main{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:24px;padding-top:0}.cview{min-width:0}.cpanel{display:none;padding:52px 24px 28px;border:1px solid var(--line);border-radius:18px;background:var(--surface);position:relative}.cpanel.active{display:flex;flex-direction:column;align-items:center;gap:20px}.dlbtn{display:inline-block;border:1px solid var(--line);padding:8px 14px;border-radius:24px;text-decoration:none;color:var(--paper);font-size:.85rem}.dlbtn:hover{background:var(--accent);color:var(--on-accent)}.cmenu{align-self:start;padding:18px;border:1px solid var(--line);border-radius:18px}.citem{display:block;text-align:left;width:100%;padding:14px;background:transparent;color:var(--paper);border:1px solid transparent;border-radius:10px;font:inherit;cursor:pointer}.citem small{display:block;color:var(--slate)}.citem[aria-current=true]{border-color:var(--accent);color:var(--accent)}.doc{background:#fff;color:#0C1013;box-shadow:0 8px 30px #0004;flex:none;font-family:var(--font-body)}.doc.a4{width:100%;max-width:540px;min-height:764px;padding:34px;display:flex;flex-direction:column;gap:22px}.dochead{display:flex;align-items:center;justify-content:space-between;gap:18px}.brand-logo{display:block;width:210px;max-width:100%;color:#88692D}.brand-logo svg{display:block;width:100%;height:auto}.dochead .meta{font-size:10px;color:#6A6E73;max-width:130px;text-align:right}.body{font-size:12px;line-height:1.65}.body h1{font-size:32px;line-height:1.08;font-weight:640;letter-spacing:-.035em;margin:20px 0}.body h2{font-size:15px;margin:22px 0 8px}.body .meta{font-size:10px;color:#6A6E73}.docfoot{margin-top:auto;border-top:1px solid #ccc;padding-top:12px;display:flex;flex-direction:column;gap:5px;font-size:9px;line-height:1.5;color:#555d64}.docfoot small{font-size:9px}.body table{width:100%;border-collapse:collapse;font-size:11px}.body th{font:600 9px/1.5 var(--font-mono);letter-spacing:.05em;text-transform:uppercase;text-align:left;color:#6A6E73}.body th,.body td{padding:10px 8px 10px 0;border-bottom:1px solid #ddd;vertical-align:top}.note{padding:14px;background:#F4F2ED;border-left:3px solid #88692D;margin-top:20px}.totals{margin:24px 0 24px auto;max-width:260px}.totals p{display:flex;justify-content:space-between;gap:20px}.c85{width:340px;max-width:100%;aspect-ratio:85/55;padding:22px}.card-front{height:100%;display:flex;flex-direction:column;justify-content:space-between;font-size:12px}.card-front h2,.signature h2{font-size:18px;margin:0}.card-front p{margin:0;color:#6A6E73}.card-front .brand-logo{width:210px}.card-front small{font:9px var(--font-mono);color:#6A6E73}.sigstrip{width:520px;max-width:100%;padding:28px}.signature{font-size:14px;line-height:1.6}.signature .brand-logo{margin-bottom:18px}.signature p{margin:6px 0}.muted{color:#6A6E73}.pagefoot{font-size:13px;color:var(--slate)}:focus-visible{outline:2px solid var(--accent-text);outline-offset:4px}@media(max-width:800px){main{grid-template-columns:1fr}.cmenu{grid-row:1;display:flex;overflow:auto;padding:8px}.citem{flex:0 0 150px}.doc.a4{padding:22px;min-height:700px}.dochead{flex-wrap:wrap}.cpanel{padding:26px 12px}.body h1{font-size:27px}}@media print{@page{margin:0}html,body{margin:0!important;padding:0!important;background:#fff!important;height:auto!important}body>*{display:none!important}main{display:block!important;margin:0!important;padding:0!important;max-width:none!important}.cmenu,.dlbtn{display:none!important}.cview{display:block!important}.cpanel{display:none!important;padding:0!important;margin:0!important;border:0!important;background:none!important;border-radius:0!important;box-shadow:none!important}.cpanel.active{display:block!important}.doc{box-shadow:none!important;margin:0!important;break-after:avoid;break-inside:avoid}.doc.a4{width:210mm!important;max-width:none!important;height:296mm!important;min-height:0!important;padding:17mm 18mm 19mm!important;display:flex!important;gap:8mm!important}.body{font-size:10.5pt}.body h1{font-size:28pt}.body h2{font-size:13pt}.body table{font-size:9pt}.body th{font-size:8pt}.docfoot{font-size:8pt;padding-top:3mm}.docfoot small{font-size:7pt}.dochead .meta,.body .meta{font-size:8pt}.brand-logo{width:55mm}.c85{width:85mm!important;max-width:85mm!important;height:55mm!important;aspect-ratio:auto!important;padding:5mm!important}.card-front{font-size:9pt}.card-front .brand-logo{width:53mm}.card-front h2{font-size:13pt}.card-front small{font-size:6pt}.sigstrip{width:180mm!important;max-width:none!important;padding:10mm!important}}'''
sections=''.join(f'<section class="cpanel{" active" if i==0 else ""}" data-doc="{slug}"><article class="doc {"c85" if i==0 else "sigstrip" if i==1 else "a4"}">{body}</article><a class="dlbtn" href="downloads/{slug}.pdf" download>Download PDF</a></section>' for i,(slug,title,size,body) in enumerate(docs))
menu=''.join(f'<button class="citem" type="button" aria-current="{str(i==0).lower()}" data-target="{slug}">{title}<small>{size}</small></button>' for i,(slug,title,size,body) in enumerate(docs))
html=f'''<!doctype html><html lang="en" data-package="forge"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Collateral — ninetynine</title><meta name="description" content="Approved ninetynine stationery and specimen business documents. Forge colours, Inter Tight typography and ninetynine.eu."><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/fonts/fonts.css"><script src="assets/theme.js?v={VERSION}"></script><style>{css}</style></head><body><header class="page"><p class="eyebrow">ninetynine · final identity</p><h1>One identity.<br>Every business document.</h1><p>Forge colours, Inter Tight typography and the approved 99 + ninetynine logo. Six downloadable documents, with clearly fictional examples. The PDF files use the approved primary logo.</p><a href="index.html">Brand guidelines</a></header><main><div class="cview">{sections}</div><aside class="cmenu" aria-label="Choose a document">{menu}</aside></main><footer class="pagefoot">{EXAMPLE} Registered details require confirmation. Website and email labels do not provision DNS or mailboxes.</footer><script>document.querySelectorAll('.citem').forEach(function(b){{b.addEventListener('click',function(){{document.querySelectorAll('.cpanel').forEach(function(p){{p.classList.toggle('active',p.dataset.doc===b.dataset.target)}});document.querySelectorAll('.citem').forEach(function(x){{x.setAttribute('aria-current',String(x===b))}})}})}});</script></body></html>'''
(SITE/'collateral.html').write_text(html)
print('Built six approved specimen collateral documents')
